def normalize_tags(tags):
    if not tags:
        return None

    seen = set()
    normalized = []

    for tag in tags:
        key = tag.casefold()
        if key not in seen:
            seen.add(key)
            normalized.append(tag)

    return tuple(normalized)

def most_common_word(words):
    counts = {}
    most_common = None
    highest_count = 0

    for word in words:
        counts[word] = counts.get(word, 0) + 1
        if counts[word] > highest_count:
            most_common = word
            highest_count = counts[word]

    return most_common

def intersection_labels(first, second):
    if not first or not second:
        return None

    second_labels = {label.casefold() for label in second}
    seen = set()
    result = []

    for label in first:
        normalized = label.casefold()
        if normalized in second_labels and normalized not in seen:
            seen.add(normalized)
            result.append(label)

    return tuple(result)

def common_suffix(words):
    words = tuple(words)
    if not words:
        return None

    first = words[0]
    limit = min(len(word) for word in words)
    length = 0

    while length < limit and all(
        word[-length - 1].casefold() == first[-length - 1].casefold()
        for word in words[1:]
    ):
        length += 1

    return first[-length:] if length else ""

def parse_clock(text):
    import re

    match = re.fullmatch(r"(\d{1,2}):(\d{2}) (AM|PM)", text, re.IGNORECASE)
    if not match:
        raise ValueError("invalid clock value")

    hour, minute = int(match.group(1)), int(match.group(2))
    period = match.group(3).upper()
    if not 1 <= hour <= 12 or not 0 <= minute <= 59:
        raise ValueError("invalid clock value")

    return (hour % 12 + (12 if period == "PM" else 0)) * 60 + minute

def sort_events(events):
    from datetime import datetime

    events = tuple(events)
    if not events:
        return None

    def event_time(event):
        value = event["time"]
        if value.endswith("Z"):
            value = value[:-1] + "+00:00"
        return datetime.fromisoformat(value)

    return tuple(sorted(events, key=event_time))

def matrix_multiply(left, right):
    if not left or not right:
        return None

    rows = len(left)
    shared = len(left[0])
    columns = len(right[0])

    return [
        [
            sum(left[i][k] * right[k][j] for k in range(shared))
            for j in range(columns)
        ]
        for i in range(rows)
    ]

def count_islands(grid):
    if not grid:
        return None

    columns = len(grid[0])
    if any(len(row) != columns for row in grid):
        raise ValueError("grid must be rectangular")

    rows = len(grid)
    visited = set()
    islands = 0

    for row in range(rows):
        for col in range(columns):
            if grid[row][col] != 1 or (row, col) in visited:
                continue

            islands += 1
            stack = [(row, col)]
            visited.add((row, col))

            while stack:
                current_row, current_col = stack.pop()
                for next_row, next_col in (
                    (current_row - 1, current_col),
                    (current_row + 1, current_col),
                    (current_row, current_col - 1),
                    (current_row, current_col + 1),
                ):
                    if (
                        0 <= next_row < rows
                        and 0 <= next_col < columns
                        and grid[next_row][next_col] == 1
                        and (next_row, next_col) not in visited
                    ):
                        visited.add((next_row, next_col))
                        stack.append((next_row, next_col))

    return islands
